const rankedItems = $input.all().map((item) => item.json).filter((item) => item.source_url);
const publisherCounts = new Map();
const sourceItems = [];
for (const item of rankedItems.sort((a, b) => b.trend_score - a.trend_score)) {
  const count = publisherCounts.get(item.publisher) ?? 0;
  if (count >= 6) continue;
  publisherCounts.set(item.publisher, count + 1);
  sourceItems.push(item);
  if (sourceItems.length >= 45) break;
}
if (sourceItems.length < 5) throw new Error('RESEARCH_INSUFFICIENT_TOOL_SIGNALS');
const prompt = `You are an evidence-first researcher and SEO strategist for short videos aimed at software developers. Analyze only the RANKED SOURCE MATERIAL below. Never invent product capabilities, adoption numbers, pricing, release dates, or market claims.

Find new AI tools and developer infrastructure that materially make developers faster or safer. Prioritize coding agents, AI IDEs, agent harnesses, MCP and tool-calling systems, automation platforms, local AI, testing and evals, observability and tracing, deployment tools, open-source frameworks, SDKs, and APIs. Explain the concrete developer workflow improved: what painful step changes, who benefits, and how a developer would use the tool.

Use trend_score as a discovery signal, not proof. Prefer recent releases, evidence from authoritative sources, repeated mentions across independent publishers, specific capabilities, and topics with clear search intent. Reject generic AI news, consumer-only apps, vague thought leadership, unsupported hype, token-price speculation, and tools without a concrete developer use case.

Choose exactly 5 candidates and one recommendation suitable for a factual, fast-paced 30-second vertical reel. Each candidate must have at least one source URL; the recommendation should use two independent sources when available. Every factual claim must cite an exact source_url from the material.

Create an SEO brief around how developers would search for the tool. Use natural keywords, not keyword stuffing. Titles should promise a concrete benefit without fake urgency. Hashtags must be relevant and limited to 5-8.

Return ONLY valid JSON matching this schema:
{"recommended_topic":{"topic":"","tool_name":"","category":"","one_line_value":"","developer_workflow":"","who_it_helps":"","why_now":"","hook":"","why_it_matters":"","visual_angle":"","trend_score":0,"claims":[{"claim_id":"c1","statement":"","source_url":"","publisher":"","published_at":"","retrieved_at":"${new Date().toISOString()}","confidence":0.0,"verification_notes":""}],"seo_brief":{"primary_keyword":"","related_keywords":[""],"search_intent":"informational|commercial|tutorial","title_options":["","",""],"description":"","hashtags":[""]}},"candidates":[{"topic":"","tool_name":"","category":"","developer_workflow":"","why_now":"","trend_score":0,"source_urls":[""]}],"research_policy":{"requires_human_review":true,"content_disclosure":"AI-assisted research and narration; edited visuals."}}

RANKED SOURCE MATERIAL:
${JSON.stringify(sourceItems)}`;
return [{ json: { prompt, source_count: sourceItems.length, sources: sourceItems, scoring_version: 'developer-tools-v1' } }];

const rawItems = $input.all().map((item) => item.json);
const now = Date.now();
const developerTerms = ['developer', 'coding', 'code', 'agent', 'agentic', 'mcp', 'model context protocol', 'ide', 'cli', 'sdk', 'api', 'automation', 'workflow', 'testing', 'evaluation', 'observability', 'open source', 'framework', 'debug', 'deploy'];
const harnessTerms = ['agent harness', 'orchestration', 'tool calling', 'computer use', 'memory', 'evals', 'sandbox', 'guardrail', 'tracing', 'prompt management'];
const authorityWeights = { 'openai.com': 18, 'github.blog': 18, 'huggingface.co': 17, 'blog.google': 17, 'aws.amazon.com': 16, 'vercel.com': 15, 'blog.jetbrains.com': 15, 'producthunt.com': 10, 'dev.to': 8 };
const normalized = [];
const seen = new Set();
for (const item of rawItems) {
  const sourceUrl = String(item.link ?? item.guid ?? '').trim();
  if (!sourceUrl || seen.has(sourceUrl)) continue;
  seen.add(sourceUrl);
  const publisher = (sourceUrl.split('://')[1] ?? '').split('/')[0].split('?')[0].split('#')[0].replace(/^www\./, '').toLowerCase() || 'unknown';
  const title = String(item.title ?? '').trim();
  const summary = String(item.contentSnippet ?? item.content ?? item.description ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 900);
  const searchable = `${title} ${summary}`.toLowerCase();
  const publishedAt = item.isoDate ?? item.pubDate ?? item.updated ?? '';
  const publishedMs = Date.parse(publishedAt);
  const ageDays = Number.isFinite(publishedMs) ? Math.max(0, (now - publishedMs) / 86400000) : 365;
  const recencyScore = ageDays <= 2 ? 30 : ageDays <= 7 ? 24 : ageDays <= 14 ? 17 : ageDays <= 30 ? 10 : 3;
  const developerHits = developerTerms.filter((term) => searchable.includes(term));
  const harnessHits = harnessTerms.filter((term) => searchable.includes(term));
  const developerRelevance = Math.min(30, developerHits.length * 5 + harnessHits.length * 4);
  const authorityScore = Object.entries(authorityWeights).find(([domain]) => publisher.includes(domain))?.[1] ?? 6;
  const toolTokens = [...new Set(title.toLowerCase().match(/[a-z][a-z0-9+.-]{2,}/g) ?? [])].filter((token) => !developerTerms.includes(token) && !['with', 'from', 'your', 'this', 'that', 'the', 'and', 'for', 'new'].includes(token));
  normalized.push({ title, summary, source_url: sourceUrl, publisher, published_at: publishedAt, age_days: Math.round(ageDays * 10) / 10, recency_score: recencyScore, developer_relevance: developerRelevance, authority_score: authorityScore, matched_developer_terms: developerHits, matched_harness_terms: harnessHits, tool_tokens: toolTokens.slice(0, 8) });
}
const tokenSources = new Map();
for (const item of normalized) for (const token of item.tool_tokens) {
  if (!tokenSources.has(token)) tokenSources.set(token, new Set());
  tokenSources.get(token).add(item.publisher);
}
for (const item of normalized) {
  const crossSourceMentions = Math.max(1, ...item.tool_tokens.map((token) => tokenSources.get(token)?.size ?? 1));
  const momentumScore = Math.min(22, (crossSourceMentions - 1) * 7 + Math.min(8, item.tool_tokens.length));
  item.cross_source_mentions = crossSourceMentions;
  item.momentum_score = momentumScore;
  item.trend_score = Math.min(100, item.recency_score + item.developer_relevance + item.authority_score + momentumScore);
  item.seo_terms = [...new Set([...item.matched_developer_terms, ...item.matched_harness_terms, ...item.tool_tokens.slice(0, 4)])].slice(0, 10);
}
const ranked = normalized.filter((item) => item.developer_relevance >= 5).sort((a, b) => b.trend_score - a.trend_score).slice(0, 60);
if (ranked.length < 5) throw new Error('INSUFFICIENT_DEVELOPER_TOOL_SIGNALS');
return ranked.map((json) => ({ json }));

const originalPrompt = $items('Build Research Prompt')[0]?.json?.prompt ?? '';
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
const errorType = String(body?.error?.type ?? body?.type ?? '').trim();
if (statusCode >= 200 && statusCode < 300 && text) {
  return [{ json: { use_qwen_fallback: false, response: text, research_provider: 'anthropic', research_model: body?.model ?? 'claude', prompt: originalPrompt } }];
}
const fallbackReason = statusCode < 200 || statusCode >= 300 ? `${statusCode}_${errorType || 'http_error'}` : 'empty_response';
return [{ json: { use_qwen_fallback: true, prompt: originalPrompt, research_provider: 'qwen-fallback', fallback_reason: fallbackReason } }];

const promptItem = $items('Build Peter and Stewie Dialogue Prompt')[0]?.json ?? {};
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
const errorType = String(body?.error?.type ?? body?.type ?? '').trim();
if (statusCode >= 200 && statusCode < 300 && text) {
  return [{ json: { use_qwen_fallback: false, response: text, dialogue_provider: 'anthropic', dialogue_model: body?.model ?? 'claude', prompt: promptItem.prompt, research: promptItem.research, seo_brief: promptItem.seo_brief } }];
}
const fallbackReason = statusCode < 200 || statusCode >= 300 ? `${statusCode}_${errorType || 'http_error'}` : 'empty_response';
return [{ json: { use_qwen_fallback: true, prompt: promptItem.prompt, research: promptItem.research, seo_brief: promptItem.seo_brief, dialogue_provider: 'qwen-fallback', fallback_reason: fallbackReason } }];

const payload = $json;
let raw = '';
if (typeof payload === 'string') raw = payload;
else if (typeof payload.body === 'string') raw = payload.body;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.response === 'string') raw = payload.response;
else raw = JSON.stringify(payload);
if (!raw) throw new Error('RESEARCH_EMPTY_RESPONSE');
let generated = raw;
if (raw.includes('\n')) {
  const chunks = raw.split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
  generated = chunks.map((chunk) => chunk.response ?? '').join('');
} else {
  try { generated = JSON.parse(raw).response ?? raw; } catch {}
}
const cleaned = generated.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
let research;
try { research = JSON.parse(cleaned); } catch (error) { throw new Error(`RESEARCH_INVALID_JSON: ${error.message}`); }
if (!research.recommended_topic?.claims?.length) throw new Error('RESEARCH_NO_RECOMMENDED_CLAIMS');
const provider = payload.research_provider ?? 'qwen-fallback';
const model = payload.research_model ?? 'tushin-agent:latest';
return [{ json: { research, researched_at: new Date().toISOString(), research_provider: provider, model, requires_human_review: true } }];

const research = $json.research;
const topic = research?.recommended_topic;
if (!topic) throw new Error('SEO_MISSING_RECOMMENDED_TOPIC');
const incoming = topic.seo_brief ?? {};
const toolName = String(topic.tool_name ?? topic.topic ?? 'AI developer tool').trim();
const primaryKeyword = String(incoming.primary_keyword ?? `${toolName} for developers`).trim();
const relatedKeywords = [...new Set((Array.isArray(incoming.related_keywords) ? incoming.related_keywords : []).map((value) => String(value).trim()).filter(Boolean))].slice(0, 8);
const titleOptions = [...new Set((Array.isArray(incoming.title_options) ? incoming.title_options : []).map((value) => String(value).trim()).filter(Boolean))].slice(0, 5);
if (!titleOptions.length) titleOptions.push(`${toolName}: the developer workflow it improves`);
const hashtags = [...new Set((Array.isArray(incoming.hashtags) ? incoming.hashtags : []).map((value) => `#${String(value).replace(/^#/, '').replace(/[^A-Za-z0-9_]/g, '')}`).filter((value) => value.length > 1))].slice(0, 8);
for (const fallback of ['#AITools', '#DeveloperTools', '#Coding']) { if (hashtags.length >= 5) break; if (!hashtags.includes(fallback)) hashtags.push(fallback); }
const seoBrief = { primary_keyword: primaryKeyword, related_keywords: relatedKeywords, search_intent: incoming.search_intent ?? 'informational', title_options: titleOptions, description: String(incoming.description ?? topic.one_line_value ?? topic.why_it_matters ?? '').trim(), hashtags };
research.recommended_topic.seo_brief = seoBrief;
return [{ json: { ...$json, research, seo_brief: seoBrief } }];

const research = $json.research;
if (!research?.recommended_topic) throw new Error('SCRIPT_MISSING_RESEARCH');
const topic = research.recommended_topic;
const prompt = `Write a clean, evidence-based dialogue for a 30-second vertical video about the recommended AI developer tool below. Return exactly six short alternating turns, beginning with Peter.

Dialogue structure:
1. Peter introduces the tool and the developer pain it addresses.
2. Stewie asks why it is needed.
3. Peter explains the concrete workflow or capability.
4. Stewie questions how it can be used or whether it is genuinely useful.
5. Peter answers with a specific evidence-backed benefit.
6. Stewie gives a concise, slightly skeptical but positive closing takeaway.

Focus on one primary tool and one coherent use case. Do not combine unrelated products, models, or claims in the same dialogue. Every turn must be one sentence: complete, conversational, and written with simple grammar and a clear subject. Keep the entire dialogue between 55–68 words. Peter is plain-spoken and mildly funny; Stewie is precise, skeptical, and witty. Keep every line clean, natural, and easy to say aloud. Name the tool early, use the primary SEO keyword naturally at most once, and never include stage directions, headings, URLs, profanity, keyword stuffing, sentence fragments, or unsupported hype. Use only facts from the research package.

After writing the dialogue, plan 4–8 relevant internet image cues. Each cue must name an exact phrase spoken in its zero-based turn_index, a focused image-search query, kind logo or screenshot, a visual_purpose of identity, interface, mechanism, or outcome, and a source_url to the relevant product, documentation, article or repository page. Use provided research URLs where possible. Never invent direct image URLs. Include different useful views: product identity, the actual UI/workflow, a feature or diagram, and a concrete outcome. Match the visual to the spoken claim. No generic title cards.

Return ONLY JSON: {"title":"","focus":"","source_start_seconds":0,"turns":[{"speaker":"peter","text":""},{"speaker":"stewie","text":""},{"speaker":"peter","text":""},{"speaker":"stewie","text":""},{"speaker":"peter","text":""},{"speaker":"stewie","text":""}],"visuals":[{"turn_index":0,"phrase":"exact spoken phrase","query":"tool name screenshot","kind":"screenshot","visual_purpose":"interface","source_url":"https://official-source-page"}]}
RECOMMENDED RESEARCH:
${JSON.stringify(topic)}`;
return [{ json: { prompt, research, seo_brief: $json.seo_brief, source_start_seconds: 0 } }];

const payload = $json;
let raw = '';
if (typeof payload === 'string') raw = payload;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.body === 'string') raw = payload.body;
else if (typeof payload.response === 'string') raw = payload.response;
else raw = JSON.stringify(payload);
if (!raw) throw new Error('DIALOGUE_EMPTY_RESPONSE');
const lines = raw.split(/\r?\n/).filter(Boolean);
let generated = raw;
if (lines.length > 1) {
  const chunks = lines.map((line) => JSON.parse(line));
  generated = chunks.map((chunk) => chunk.response ?? '').join('');
} else {
  try { generated = JSON.parse(raw).response ?? raw; } catch {}
}
let dialoguePackage;
const end = generated.lastIndexOf('}');
for (const start of [0, ...[...generated.matchAll(/\{/g)].map((match) => match.index)]) {
  if (end < start) continue;
  try {
    const parsed = JSON.parse(generated.slice(start, end + 1));
    if (Array.isArray(parsed.turns)) { dialoguePackage = parsed; break; }
  } catch {}
}
if (!dialoguePackage || dialoguePackage.turns.length !== 6) throw new Error('DIALOGUE_REQUIRES_SIX_TURNS');
const expected = ['peter', 'stewie', 'peter', 'stewie', 'peter', 'stewie'];
const dialogue = dialoguePackage.turns.map((turn, index) => {
  const speaker = String(turn.speaker ?? '').toLowerCase().trim();
  if (speaker !== expected[index]) throw new Error(`DIALOGUE_SPEAKER_ORDER:${index}`);
  const text = String(turn.text ?? '').replace(/\s+/g, ' ').trim();
  if (!text) throw new Error(`DIALOGUE_EMPTY_TURN:${index}`);
  return { speaker, text, turn_index: index, audio_path: `/media/dialogue-${index}-${speaker}.wav` };
});
const wordCount = dialogue.reduce((sum, turn) => sum + turn.text.split(/\s+/).length, 0);
if (wordCount < 48 || wordCount > 72) throw new Error(`DIALOGUE_WORD_COUNT:${wordCount}`);
const metadata = { title: String(dialoguePackage.title ?? ''), focus: String(dialoguePackage.focus ?? ''), source_start_seconds: Number(dialoguePackage.source_start_seconds ?? 0), visuals: Array.isArray(dialoguePackage.visuals) ? dialoguePackage.visuals : [], research: payload.research };
return dialogue.map((turn) => ({ json: { ...turn, dialogue, ...metadata } }));

const jobs = $items('Normalize Peter and Stewie Dialogue').map((item) => item.json).sort((a, b) => a.turn_index - b.turn_index);
if (jobs.length !== 6) throw new Error(`RENDER_REQUIRES_SIX_DIALOGUE_TURNS:${jobs.length}`);
const first = jobs[0];
const dialogue = jobs.map((job) => ({ speaker: job.speaker, text: job.text, turn_index: job.turn_index, audioPath: job.audio_path }));
const research = $items('Build Peter and Stewie Dialogue Prompt')[0].json.research;
return [{json:{sourceVideo:'/media/source.mp4',voiceOverlay:null,pngOverlay:null,characterImages:{peter:'/media/peter.png',stewie:'/media/stewie.png'},startFrame:Math.round(Number(first.source_start_seconds ?? 0)*30),durationInFrames:900,dialogue,visualCues:first.visuals || [],visuals:[],title:first.title,focus:first.focus,research,requires_human_review:true}}];
